UPDATE achats.produits p
SET article_id = dev.article_id, contenance = dev.contenance, unite = dev.unite
FROM dev
WHERE p.enseigne_id = dev.enseigne_id AND p.libelle = dev.libelle
  AND (p.article_id IS DISTINCT FROM dev.article_id OR p.contenance IS DISTINCT FROM dev.contenance OR p.unite IS DISTINCT FROM dev.unite);

-- Après l'alignement, sinon il serait écrasé : 140 g, pas 1 kg.
UPDATE achats.produits SET contenance = 0.14, unite = 'kg' WHERE libelle = 'RM NAT RAC BURGER140';
